# Tabs Tabs Набор компонентов для создания вкладок.
Структура для вкладок похожа на структуру маркированных списков. ## Tabs Tabs ## TabItem TabItem :::caution Взаимоисключающие свойства
Свойство  `value`  - это значение Tab. Оно отображается справа от основного текста. 
 `value`  и  `contentRight`  взаимоисключающие: если передано одно, второе передать нельзя.
::: ## TabsController (deprecated) TabsController (deprecated) Вместо этого используйте Tabs, TabItem, указав параметры index, itemIndex, onIndexChange. ## Использование Использование ### Стандартное подключение, без клавиатурной навигации Стандартное подключение, без клавиатурной навигации ```tsx
import React, { useState } from 'react';
import { Tabs, TabItem } from '@salutejs/sdds-finai';
import { IconClock } from '@salutejs/plasma-icons';

export function App() {
    const items = Array(4).fill(0);
    const [index, setIndex] = useState(0);

    return (
        <div>
            <Tabs view="filled" stretch size="xs">
                {items.map((_, i) => (
                    <TabItem
                        view="secondary"
                        key={`item:${i}`}
                        size="xs"
                        selected={i === index}
                        tabIndex={0}
                        contentLeft={<IconClock size="xs" color="inherit" />}
                        onClick={() => setIndex(i)}
                    >
                        {`Label${i + 1}`}
                    </TabItem>
                ))}
            </Tabs>
        </div>
    );
}
```

### Расположение Tabs Расположение Tabs Компонент может быть горизонтальными (по умолчанию) и вертикальными. За это отвечает свойство  `orientation` . ```tsx
import React, { useState } from 'react';
import { Tabs, TabItem } from '@salutejs/sdds-finai';
import { IconClock } from '@salutejs/plasma-icons';

export function App() {
    const items = Array(8).fill(0);
    const [index, setIndex] = useState(0);

    return (
        <div>
            <Tabs view="divider" orientation="vertical" size="xs" style={{ width: '15rem' }}>
                {items.map((_, i) => (
                    <TabItem
                        view="divider"
                        orientation="vertical"
                        key={`item:${i}`}
                        size="xs"
                        selected={i === index}
                        tabIndex={0}
                        contentLeft={<IconClock size="xs" color="inherit" />}
                        onClick={() => setIndex(i)}
                    >
                        {`Label${i + 1}`}
                    </TabItem>
                ))}
            </Tabs>
        </div>
    );
}
```

### Расположение divider у вертикальных Tabs Расположение divider у вертикальных Tabs Для вертикальных Tabs можно расположить разделитель ( `divider` ) слева (по умолчанию) или справа с помощью свойства  `dividerAlign` . ```tsx
import React, { useState } from 'react';
import { Tabs, IconTabItem } from '@salutejs/sdds-finai';
import { IconClock } from '@salutejs/plasma-icons';

export function App() {
    const items = Array(4).fill(0);
    const [leftIndex, setLeftIndex] = useState(0);
    const [rightIndex, setRightIndex] = useState(0);

    return (
        <div style={{ display: 'flex', gap: '2rem' }}>
            <Tabs view="divider" orientation="vertical" dividerAlign="left" size="xs" style={{ width: '15rem' }}>
                {items.map((_, i) => (
                    <IconTabItem
                        view="divider"
                        orientation="vertical"
                        key={`item:${i}`}
                        size="xs"
                        selected={i === leftIndex}
                        tabIndex={0}
                        onClick={() => setLeftIndex(i)}
                    >
                        <IconClock size="xs" color="inherit" />
                    </IconTabItem>
                ))}
            </Tabs>

            <Tabs view="divider" orientation="vertical" dividerAlign="right" size="xs" style={{ width: '15rem' }}>
                {items.map((_, i) => (
                    <IconTabItem
                        view="divider"
                        orientation="vertical"
                        key={`item:${i}`}
                        size="xs"
                        selected={i === rightIndex}
                        tabIndex={0}
                        onClick={() => setRightIndex(i)}
                    >
                        <IconClock size="xs" color="inherit" />
                    </IconTabItem>
                ))}
            </Tabs>
        </div>
    );
}
```

### Пример с прокруткой Пример с прокруткой При выборе Tab происходит прокрутка до выбранного TabItem. ```tsx
import React, { useState } from 'react';
import { Tabs, TabItem, Button } from '@salutejs/sdds-finai';
import { IconClock } from '@salutejs/plasma-icons';

export function App() {
    const items = Array(8).fill(0);
    const [index, setIndex] = useState(0);

    const specificIndex = 6;

    return (
        <div style={{ display:'flex', flexDirection: 'column', gap: '1rem' }}>
            <Tabs view="divider" size="xs" style={{ width: '15rem' }}>
                {items.map((_, i) => (
                    <TabItem
                        view="divider"
                        key={`item:${i}`}
                        size="xs"
                        selected={i === index}
                        tabIndex={0}
                        contentLeft={<IconClock size="xs" color="inherit" />}
                        onClick={() => setIndex(i)}
                    >
                        {`Label${i + 1}`}
                    </TabItem>
                ))}
            </Tabs>

            <Button onClick={() => setIndex(specificIndex)}>{`Выбрать элемент ${specificIndex + 1}`}</Button>
        </div>
    );
}
```

### Пример с Dropdown Пример с Dropdown ```tsx
import React, { useState } from 'react';
import { Tabs, TabItem, Dropdown } from '@salutejs/sdds-finai';

export function App() {
    const items = Array(8).fill(0);
    const [index, setIndex] = useState(0);

    const maxItemQuantity = 3;
    const visibleItems = items.slice(0, maxItemQuantity);
    const otherItems = items.slice(maxItemQuantity);

    const dropdownItems = otherItems.map((_, i) => {
        const itemIndex = maxItemQuantity + i;

        return {
            label: `Label${itemIndex + 1}`,
            value: itemIndex,
        };
    });

    return (
        <div style={{ height: '15rem', alignItems: 'flex-start' }}>
            <Tabs clip="showAll" view="divider" size="xs">
                {visibleItems.map((_, i) => (
                    <TabItem
                        key={`item:${i}`}
                        view="divider"
                        selected={i === index}
                        onClick={() => setIndex(i)}
                        tabIndex={0}
                        size="xs"
                    >
                        {`Label${i + 1}`}
                    </TabItem>
                ))}
                {dropdownItems.length > 0 && (
                    <div style={{ marginLeft: '1.75rem' }}>
                        <Dropdown size="xs" items={dropdownItems} onItemSelect={(item) => setIndex(item.value)}>
                            <TabItem key="item:ShowAll" view="divider" tabIndex={0} size="xs">
                                ShowAll
                            </TabItem>
                        </Dropdown>
                    </div>
                )}
            </Tabs>
        </div>
    );
}
```

### Пример с Dropdown и перемещением выбранного элемента в видимую область Пример с Dropdown и перемещением выбранного элемента в видимую область При выборе элемента в Dropdown он перемещается в видимую область (на последнее видимое место),
а крайний видимый TabItem, который он вытеснил, уходит в Dropdown. ```tsx
import React, { useState } from 'react';
import { Tabs, TabItem, Dropdown } from '@salutejs/sdds-finai';

export function App() {
    const items = Array(8).fill(0);

    const maxItemQuantity = 3;

    const [order, setOrder] = useState(items.map((_, i) => i));
    const [selected, setSelected] = useState(order[0]);

    const visibleItems = order.slice(0, maxItemQuantity);
    const otherItems = order.slice(maxItemQuantity);

    const dropdownItems = otherItems.map((itemIndex) => ({
        label: `Label${itemIndex + 1}`,
        value: itemIndex,
    }));

    const onSelectDropdownItem = (item) => {
        setOrder((prevOrder) => {
            const newOrder = prevOrder.filter((itemIndex) => itemIndex !== item.value);
            newOrder.splice(maxItemQuantity - 1, 0, item.value);

            return newOrder;
        });
        setSelected(item.value);
    };

    return (
        <div style={{ height: '15rem', alignItems: 'flex-start' }}>
            <Tabs clip="showAll" view="divider" size="xs">
                {visibleItems.map((itemIndex) => (
                    <TabItem
                        key={`item:${itemIndex}`}
                        view="divider"
                        selected={itemIndex === selected}
                        onClick={() => setSelected(itemIndex)}
                        tabIndex={0}
                        size="xs"
                    >
                        {`Label${itemIndex + 1}`}
                    </TabItem>
                ))}
                {dropdownItems.length > 0 && (
                    <div style={{ marginLeft: '1.75rem' }}>
                        <Dropdown size="xs" items={dropdownItems} onItemSelect={onSelectDropdownItem}>
                            <TabItem key="item:ShowAll" view="divider" tabIndex={0} size="xs">
                                ShowAll
                            </TabItem>
                        </Dropdown>
                    </div>
                )}
            </Tabs>
        </div>
    );
}
```

### Подключение клавиатурной навигации Подключение клавиатурной навигации Для этого необходимо дополнительно прокинуть свойства  `index, itemIndex, onIndexChange` . 
Для горизонтальных Tabs: клавиши ArrowLeft, ArrowRight, Home, End для навигации по вкладкам. 
Для вертикальных Tabs: клавиши ArrowUp, ArrowDown, Home, End для навигации по вкладкам. ```tsx
import React, { useState } from 'react';
import { Tabs, TabItem } from '@salutejs/sdds-finai';
import { IconClock } from '@salutejs/plasma-icons';

export function App() {
    const items = Array(4).fill(0);
    const [horizontalIndex, setHorizontalIndex] = useState(0);
    const [verticalIndex, setVerticalIndex] = useState(0);

    return (
        <div style={{ display: "flex", flexDirection: "column", gap: "50px"}}>
            <div>
                <Tabs view="divider" stretch size="xs" index={horizontalIndex}>
                    {items.map((_, i) => (
                        <TabItem
                            view="divider"
                            key={`item:${i}`}
                            size="xs"
                            itemIndex={i}
                            onIndexChange={(i) => setHorizontalIndex(i)}
                            selected={i === horizontalIndex}
                            tabIndex={0}
                            contentLeft={<IconClock size="xs" color="inherit" />}
                            onClick={() => setHorizontalIndex(i)}
                        >
                            {`Label${i + 1}`}
                        </TabItem>
                    ))}
                </Tabs>
            </div>

            <div>
                <Tabs orientation="vertical" view="divider" size="xs" index={verticalIndex}>
                    {items.map((_, i) => (
                        <TabItem
                            orientation="vertical"
                            view="divider"
                            key={`item:${i}`}
                            size="xs"
                            itemIndex={i}
                            onIndexChange={(i) => setVerticalIndex(i)}
                            selected={i === verticalIndex}
                            tabIndex={0}
                            contentLeft={<IconClock size="xs" color="inherit" />}
                            onClick={() => setVerticalIndex(i)}
                        >
                            {`Label${i + 1}`}
                        </TabItem>
                    ))}
                </Tabs>
            </div>
        </div>
    );
}
```
